insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1culture-grammar','To film, ___ bohater wraca po latach do rodzinnego miasta.','["w którym","którego","któremu"]',0,'После w filmie относительное местоимение принимает форму w którym.',0),
('b1culture-grammar','Poznałam reżyserkę, ___ film zdobył nagrodę.','["której","którą","któremu"]',0,'Форма której выражает принадлежность: фильм этой режиссёрки.',1),
('b1culture-grammar','Aktor, ___ publiczność nagrodziła brawami, zagrał bardzo naturalnie.','["którego","który","któremu"]',0,'Глагол nagrodzić требует винительного падежа; для лица мужского рода — którego.',2),
('b1culture-grammar','Książka była ___: długo myślałem o decyzji bohatera.','["poruszająca","poruszona","poruszająco"]',0,'Poruszająca согласуется с существительным książka и оценивает произведение.',3),
('b1culture-grammar','Составьте: Это выставка, которая побуждает публику к размышлению.','["To wystawa, która skłania publiczność do refleksji.","To wystawa, której skłania publicznością refleksję.","To wystawa, który publiczność skłania do refleksją."]',0,'Która согласуется с wystawa; skłaniać kogoś do czegoś требует винительного и родительного падежей.',4),
('b1culture-grammar','Составьте: Мне понравился фильм, в котором музыка создавала тревожное настроение.','["Spodobał mi się film, w którym muzyka budowała niepokojący nastrój.","Podobałem film, którego muzyka budowała niepokojącego nastrój.","Spodobał mnie się film, który muzyką budował nastrój."]',0,'Безличное spodobał mi się требует дательного; место действия выражено w którym.',5),
('b1culture-quiz','Что означает ekranizacja?','["фильм по мотивам литературного произведения","театральная декорация","критическая статья"]',0,'Ekranizacja переносит литературное произведение на экран.',0),
('b1culture-quiz','Które słowo opisuje wydarzenia utworu?','["fabuła","publiczność","scenografia"]',0,'Fabuła — последовательность событий произведения.',1),
('b1culture-quiz','To autorka, ___ powieść właśnie przeczytałem.','["której","którą","która"]',0,'Której выражает принадлежность: роман этой авторки.',2),
('b1culture-quiz','Spektakl, ___ widzieliśmy wczoraj, był bardzo poruszający.','["który","którego","któremu"]',0,'Неодушевлённое существительное мужского рода в винительном имеет форму który.',3),
('b1culture-quiz','Jak pozytywnie ocenić grę aktora?','["Stworzył przekonującą i naturalną postać.","Fabuła siedziała na widowni.","Recenzja zagrała bohatera."]',0,'Первый вариант естественно оценивает актёрскую работу.',4),
('b1culture-quiz','Prosta ___ pomogła zbudować nastrój przedstawienia.','["scenografia","publiczność","powieść"]',0,'Scenografia — визуальное оформление сцены.',5),
('b1culture-quiz','Выберите естественное сочетание.','["skłaniać do refleksji","wywierać publicznością","oglądać wrażeniem"]',0,'Skłaniać do refleksji — побуждать к размышлению.',6),
('b1culture-quiz','Film był wielowątkowy, czyli ___.','["rozwijał kilka powiązanych historii","trwał tylko minutę","nie miał bohaterów"]',0,'Wielowątkowy значит состоящий из нескольких сюжетных линий.',7),
('b1culture-quiz','Muzeum, ___ odbywa się wystawa, mieści się w centrum.','["w którym","którego","któremu"]',0,'Место выражается конструкцией w którym.',8),
('b1culture-quiz','Która opinia jest uzasadniona?','["Film wywarł na mnie wrażenie, ponieważ obraz i muzyka tworzyły spójną całość.","Film był dobry, bo tak.","Każda ekranizacja jest lepsza od książki."]',0,'Первый вариант содержит конкретную оценку и её обоснование.',9),
('b1culture-reading-check','Dlaczego Ola wybrała się na wydarzenie?','["Chciała porównać książkę z ekranizacją","Musiała napisać szkolny egzamin","Szukała nowego mieszkania"]',0,'Она прочитала роман и хотела увидеть его экранизацию.',0),
('b1culture-reading-check','Co pokazano przed filmem?','["Wystawę szkiców i zdjęć ze scenografii","Koncert muzyki ludowej","Kurs fotografii"]',0,'Перед сеансом можно было увидеть материалы о создании сценографии.',1),
('b1culture-reading-check','Co Ola oceniła pozytywnie?','["Przekonującą grę głównej aktorki","Brak związku z książką","Puste spotkanie bez twórców"]',0,'Ей особенно понравилась убедительная игра актрисы.',2),
('b1culture-reading-check','Czym film różnił się od powieści?','["Łączył kilka postaci i skracał wątki","Dodawał wszystkie szczegóły książki","Nie miał muzyki ani obrazu"]',0,'Экранизация объединила персонажей и сократила некоторые линии.',3),
('b1culture-reading-check','Co wydarzyło się po seansie?','["Publiczność rozmawiała z reżyserką","Kino zostało natychmiast zamknięte","Ola oddała książkę autorowi"]',0,'После фильма состоялась встреча с режиссёркой.',4),
('b1culture-reading-check','Jaki wniosek wyciągnęła Ola?','["Książka i film mogą inaczej opowiadać tę samą historię","Ekranizacja zawsze powinna kopiować każde zdanie","Recenzje są ważniejsze niż własna opinia"]',0,'Главный вывод касается разных средств литературы и кино.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values
('b1culture-wieczor-z-ksiazka-i-filmem','b1-culture','Wieczór z książką i filmem','Как сравнить роман, экранизацию и культурное событие','B1',9,'🎭','["Ola niedawno przeczytała powieść o rodzeństwie, które po latach wraca do rodzinnego domu. Kiedy lokalne kino zapowiedziało pokaz ekranizacji i spotkanie z reżyserką, od razu kupiła bilet. Chciała sprawdzić, czy film zachował spokojny nastrój i wielowątkową fabułę książki.","Przed seansem publiczność mogła obejrzeć małą wystawę szkiców kostiumów oraz zdjęć miejsc, w których powstawał film. Olę zainteresowała zwłaszcza prosta scenografia domu. Dzięki światłu i starym przedmiotom wywierała mocne wrażenie, chociaż nie kopiowała dokładnie opisów z powieści.","Film skracał niektóre wątki i łączył kilka drugoplanowych postaci. Mimo to główna aktorka, której grę Ola uznała za przekonującą, dobrze pokazała zmianę bohaterki. Szczególnie poruszająca była scena bez dialogu, w której muzyka i obraz zastąpiły długi książkowy opis.","Po seansie reżyserka odpowiadała na pytania publiczności. Wyjaśniła, że ekranizacja nie musi powtarzać każdego zdania, lecz powinna zachować najważniejszy konflikt i emocje. Spotkanie skłoniło Olę do refleksji: książka i film opowiadają tę samą historię innymi środkami, dlatego warto oceniać każde dzieło osobno."]','{"rodzeństwie":{"lemma":"rodzeństwo","translation":"братья и сёстры","part_of_speech":"существительное"},"zapowiedziało":{"lemma":"zapowiedzieć","translation":"объявить","part_of_speech":"глагол"},"zachował":{"lemma":"zachować","translation":"сохранить","part_of_speech":"глагол"},"seansem":{"lemma":"seans","translation":"сеанс","part_of_speech":"существительное"},"szkiców":{"lemma":"szkic","translation":"эскиз","part_of_speech":"существительное"},"kostiumów":{"lemma":"kostium","translation":"костюм","part_of_speech":"существительное"},"powstawał":{"lemma":"powstawać","translation":"создаваться","part_of_speech":"глагол"},"zwłaszcza":{"lemma":"zwłaszcza","translation":"особенно","part_of_speech":"наречие"},"wywierała":{"lemma":"wywierać","translation":"производить","part_of_speech":"глагол"},"drugoplanowych":{"lemma":"drugoplanowy","translation":"второстепенный","part_of_speech":"прилагательное"},"uznała":{"lemma":"uznać","translation":"счесть","part_of_speech":"глагол"},"zastąpiły":{"lemma":"zastąpić","translation":"заменить","part_of_speech":"глагол"},"powtarzać":{"lemma":"powtarzać","translation":"повторять","part_of_speech":"глагол"},"konflikt":{"lemma":"konflikt","translation":"конфликт","part_of_speech":"существительное"},"środkami":{"lemma":"środek","translation":"средство","part_of_speech":"существительное"},"dzieło":{"lemma":"dzieło","translation":"произведение","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b1culture-reading-check"}',31,true)
